using AfriWallet.Fraud.DeviceRisk.Domain.Models;namespace AfriWallet.Fraud.DeviceRisk.Application.Policies;public sealed class DeviceRiskPolicy{public RiskBand ResolveBand(int score)=>score switch{>=80=>RiskBand.Critical,>=60=>RiskBand.High,>=30=>RiskBand.Medium,_=>RiskBand.Low};public RiskRecommendation ResolveRecommendation(int score)=>score switch{>=80=>RiskRecommendation.Restrict,>=60=>RiskRecommendation.Challenge,>=30=>RiskRecommendation.Review,_=>RiskRecommendation.Allow};}